<script setup lang="ts">
import {computed} from 'vue';
import type {DiscoveryPipeline} from '../../agentHost/discoveryTypes';
import {useI18n} from '../uiPorts';
const {tr}=useI18n();
const props=defineProps<{pipeline:DiscoveryPipeline;compact?:boolean}>();
const steps=computed(()=>[{key:'collecting',label:props.pipeline.collectionRunId?tr('FOFA 采集','FOFA collection'):tr('复用项目数据','Reuse project data')},{key:'local_analysis',label:tr('核验与确认','Verify and confirm')},{key:'free_discovery',label:tr('自动补证','Auto evidence gathering')},...(props.pipeline.allowHunter?[{key:'hunter',label:tr('Hunter 关联','Hunter correlation')}]:[]),{key:'steady',label:tr('合并与继续','Merge and continue')}]);
const phaseIndex=computed(()=>steps.value.findIndex(step=>step.key===({passive_evidence:'local_analysis',awaiting_scope:'local_analysis'} as Record<string,string>)[props.pipeline.phase]||step.key===props.pipeline.phase));
const stateLabel=computed(()=>({collecting:tr('正在采集初始资产','Collecting initial assets'),local_analysis:tr('整理并核验归属证据','Organizing and verifying ownership evidence'),passive_evidence:tr('补充被动证据','Adding passive evidence'),awaiting_scope:tr('等待集中确认新增范围','Waiting for batch confirmation of new scope'),free_discovery:tr('已确认范围内自动发现','Auto-discovering within the confirmed scope'),hunter:tr('精确关联并自动翻页','Exact correlation with auto paging'),steady:tr('本轮回流已保存',"This round's results are saved"),blocked:tr('已保留进度，需要处理','Progress kept; action needed'),paused:tr('已暂停，可从断点继续','Paused; can resume from the checkpoint'),waiting_storage:tr('等待本地存储，自动重试','Waiting for local storage; retrying automatically')} as Record<string,string>)[props.pipeline.phase]||props.pipeline.phase);
const metrics=computed(()=>Object.entries({collectedAssets:tr('项目记录','Project records'),verifiedGroups:tr('核验通过','Verified'),pendingEvidenceGroups:tr('自动待补证','Awaiting auto evidence'),conflicts:tr('证据冲突','Evidence conflicts'),freeCompleted:tr('已完成补证','Evidence gathered'),hunterAdded:tr('Hunter 入库记录','Hunter records stored'),roundAdded:tr('本轮新增','New this round')}).filter(([key])=>Number.isFinite(props.pipeline.counts?.[key])).map(([key,label])=>({key,label,value:props.pipeline.counts[key]})));
const compactMetrics=computed(()=>metrics.value.filter(metric=>['collectedAssets','roundAdded','freeCompleted'].includes(metric.key)));
const knownCost=computed(()=>typeof props.pipeline.hunter?.spentPoints==='number'&&Number.isFinite(props.pipeline.hunter.spentPoints));
const hunterHistory=computed(()=>props.pipeline.allowHunter||props.pipeline.hunter?.costUnknown||(props.pipeline.hunter?.queries||0)>0||(props.pipeline.hunter?.pages||0)>0||knownCost.value&&(props.pipeline.hunter.spentPoints||0)>0);
const organizationEvidence=computed(()=>props.pipeline.organizationEvidence);
function checkedTime(value:number){return Number.isFinite(value)&&value>0?new Date(value*1000).toLocaleString('zh-CN',{hour12:false}):'';}
</script>
<template>
 <section class="discovery-pipeline" :class="{compact}" :aria-label="tr('资产发现完整流程','Full asset discovery pipeline')" data-testid="discovery-pipeline">
  <ol v-if="!compact" class="pipeline-steps" :style="{'--step-count':steps.length}"><li v-for="(step,index) in steps" :key="step.key" :class="{current:phaseIndex===index,passed:phaseIndex>index}" :aria-current="phaseIndex===index?'step':undefined"><span>{{index+1}}</span>{{step.label}}</li></ol>
  <div class="pipeline-status" role="status"><strong>{{tr(`第 ${pipeline.round||1} 轮 · ${stateLabel}`,`Round ${pipeline.round||1} · ${stateLabel}`)}}</strong><span v-if="pipeline.collectionRunId">{{tr(`FOFA 任务 #${pipeline.collectionRunId}`,`FOFA job #${pipeline.collectionRunId}`)}}</span></div>
  <p v-if="pipeline.reason&&!compact" class="pipeline-reason">{{pipeline.reason}}</p>
  <dl v-if="metrics.length" class="pipeline-metrics"><div v-for="metric in compact?compactMetrics:metrics" :key="metric.key"><dt>{{metric.label}}</dt><dd>{{metric.value.toLocaleString()}}</dd></div></dl>
  <div class="pipeline-cost" :class="{unknown:pipeline.hunter?.costUnknown}" role="status">
   <template v-if="hunterHistory"><strong>Hunter</strong><span>{{tr(`${pipeline.hunter?.queries||0} 个精确查询 · ${pipeline.hunter?.pages||0} 页`,`${pipeline.hunter?.queries||0} exact queries · ${pipeline.hunter?.pages||0} pages`)}}</span><span v-if="knownCost">{{tr(`已知消耗 ${pipeline.hunter.spentPoints!.toLocaleString()} 积分`,`Known spend: ${pipeline.hunter.spentPoints!.toLocaleString()} points`)}}</span><span v-if="pipeline.hunter?.costUnknown">{{tr('部分扣费或请求结果未知，已暂停；不会自动重发。','Some charges or request results are unknown, so this is paused; nothing is resent automatically.')}}</span><span v-else-if="!knownCost">{{tr('积分回执尚未返回','Points receipt not returned yet')}}</span><span v-if="!pipeline.allowHunter">{{tr('本次仅继续免费发现，原收费记录保留','Only free discovery continues this time; earlier paid records are kept')}}</span></template>
   <template v-else>{{tr('Hunter 本次关闭','Hunter is off for this run')}}</template>
  </div>
  <details v-if="!compact&&organizationEvidence?.supported" class="organization-evidence"><summary>{{tr('目标单位关系来源','Target organization relationship source')}} · {{organizationEvidence.networkVerified?tr('已核验公开正文','Public page text verified'):organizationEvidence.names?.length?tr('已有缓存证据','Cached evidence available'):tr('等待核实','Awaiting verification')}}<span v-if="organizationEvidence.checkedAt"> · {{checkedTime(organizationEvidence.checkedAt)}}</span></summary><p v-if="organizationEvidence.names?.length">{{tr(`已核对法定名称：${organizationEvidence.names.join('、')}`,`Verified legal names: ${organizationEvidence.names.join(', ')}`)}}</p><p v-if="organizationEvidence.sourceUrl" class="organization-source">{{organizationEvidence.sourceUrl}}</p><p v-if="organizationEvidence.error" class="organization-error">{{organizationEvidence.error}}</p><p>{{tr('单位关系仅作为归属核验依据，不会因此新增域名范围或发起目标探测。','Organization relationships only serve as ownership evidence; they never add domain scope or start probing targets.')}}</p></details>
 </section>
</template>
<style scoped>
.discovery-pipeline{margin:16px 0;border:1px solid var(--line,var(--ui-line));border-radius:var(--radius-md);padding:14px;background:var(--app-bg,var(--ui-surface-raised));min-width:0;overflow-wrap:anywhere}.pipeline-steps{display:grid;grid-template-columns:repeat(var(--step-count,5),minmax(0,1fr));gap:8px;list-style:none;padding:0;margin:0 0 14px}.pipeline-steps li{display:flex;align-items:center;gap:6px;font-size:var(--text-meta);color:var(--muted,var(--ui-muted));min-width:0;line-height:1.5}.pipeline-steps li>span{display:grid;place-items:center;flex:0 0 19px;width:19px;height:19px;border:1px solid var(--line,var(--ui-line));border-radius:50%;font-size:var(--text-micro);background:var(--app-surface,var(--ui-surface))}.pipeline-steps li.current{color:var(--blue,#2875ed);font-weight:600}.pipeline-steps li.current>span{border-color:currentColor}.pipeline-steps li.passed{color:color-mix(in srgb, var(--green) 82%, var(--ui-ink))}.pipeline-status{display:flex;gap:8px 16px;align-items:center;flex-wrap:wrap;font-size:var(--text-body)}.pipeline-status>span{font-size:var(--text-meta);color:var(--muted)}.pipeline-reason{margin:6px 0 0;font-size:var(--text-meta);color:var(--muted)}.pipeline-metrics{display:flex;flex-wrap:wrap;gap:8px 20px;margin:12px 0 0}.pipeline-metrics>div{display:flex;gap:8px;font-size:var(--text-meta);align-items:baseline}.pipeline-metrics dt{color:var(--muted)}.pipeline-metrics dd{margin:0;font-weight:600;font-size:var(--text-strong)}.pipeline-cost{display:flex;gap:6px 12px;flex-wrap:wrap;border-top:1px solid var(--line);padding-top:10px;margin-top:12px;color:var(--muted);font-size:var(--text-meta)}.pipeline-cost.unknown{color:color-mix(in srgb, var(--amber) 82%, var(--ui-ink))}.compact{padding:12px}.compact .pipeline-steps{gap:6px}@media(max-width:760px){.pipeline-steps{grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.pipeline-metrics{gap:8px 14px}}@media(max-width:440px){.pipeline-steps{grid-template-columns:repeat(2,minmax(0,1fr))}.discovery-pipeline{padding:12px}}
.organization-evidence{margin-top:10px;font-size:var(--text-meta);color:var(--muted);border-top:1px solid var(--line);padding-top:10px}.organization-evidence summary{cursor:pointer}.organization-evidence p{margin:6px 0}.organization-source{overflow-wrap:anywhere}.organization-evidence .organization-error{color:color-mix(in srgb, var(--amber) 82%, var(--ui-ink))}
</style>
